answer:
function parseQuery(qs: string): Record<string, string | string[]> {
  const out: Record<string, string | string[]> = {};
  const s = qs.startsWith('?') ? qs.slice(1) : qs;
  if (!s) return out;
  for (const part of s.split('&')) {
    if (!part) continue;
    const [kRaw, vRaw = ''] = part.split('=');
    const k = decodeURIComponent(kRaw);
    const v = decodeURIComponent(vRaw);
    const cur = out[k];
    if (cur === undefined) out[k] = v; else out[k] = Array.isArray(cur) ? [...cur, v] : [cur, v];
  }
  return out;
}
